const mkB=(heroes,stage,wpn)=>{heroes=heroes.slice();if(wpn&&!canEquip(heroes[0],wpn))heroes[0]=HERO_ORDER.find(h=>canEquip(h,wpn));const s=defaultSave(0);s.gems=1e6;heroes.forEach(h=>{if(h!=='pistol')own(s,h);s.weapons[HEROES[h].wpn]=1;s.heroWpn[h]=HEROES[h].wpn;});s.slots=6;s.team=heroes.slice();if(wpn){s.weapons[wpn]=1;s.heroWpn[heroes[0]]=wpn;}const b=new Battle(s,stage||1,R());b.pause=0;return b};
t('semua 232 senjata boleh bertempur tanpa ralat',()=>{WEAPON_ORDER.forEach(w=>{const b=mkB(['pistol'],12,w);b.save.heroes.pistol=40;b.simulate(40);A.ok(['main','menang','kalah'].includes(b.state),w)})});
t('peluru berpandu mengejar',()=>{const b=mkB(['pistol'],1,'peluru_p');b.queue=[];const z=b.spawn('biasa');z.x=40;z.y=200;z.spd=0;z.evoT=-999;z.hp=z.maxHp=1e9;b.simulate(3);A.ok(z.hp<1e9)});
t('duri pagar cederakan zombie',()=>{const b=mkB(['pistol'],5);b.save.wallsOwned=50;b.save.wallActive=49;b.syncTeam();const z=b.spawn('biasa');z.hp=z.maxHp=1000;b.hitWall(z);A.ok(z.hp<1000)});
t('perisai pagar kurangkan damage',()=>{const b=mkB(['pistol'],5);b.save.wallsOwned=50;b.save.wallActive=49;b.syncTeam();const z=b.spawn('biasa');const w=b.wall;b.hitWall(z);A.ok(Math.abs((w-b.wall)-z.dmg*(1-b.ws.armor/100))<1e-6)});
t('stage 1 tanpa upgrade beri gold untuk naik taraf',()=>{const s=defaultSave(0);const b=new Battle(s,1,R());b.simulate(900);A.ok(b.earnedGold>=upCost(1))});
t('pasukan kuat menang stage awal',()=>{const b=mkB(['pistol','shotgun','mesingan','sniper','bom','laser'],2);Object.keys(b.save.heroes).forEach(h=>b.save.heroes[h]=15);b.syncTeam();A.strictEqual(b.simulate(900),'menang')});
t('pagar kebal',()=>{const b=mkB(['pistol'],8);b.god=true;A.notStrictEqual(b.simulate(300),'kalah');A.strictEqual(b.wall,b.wallMax)});
t('bunuh semua termasuk anak pembelah',()=>{const b=mkB(['pistol'],20);b.queue=[];for(let i=0;i<4;i++){const z=b.spawn('biasa');z.traits=['pembelah']}b.killAll();A.strictEqual(b.zombies.length,0)});
