const mkP=(stage)=>{const s=defaultSave(0);s.heroes.pistol=30;POWER_ORDER.forEach(p=>s.powers[p]=1);const b=new Battle(s,stage||5,R());b.pause=0;b.queue=[];return b};
const crowd=(b,n,hp)=>{for(let i=0;i<n;i++){const z=b.spawn('biasa');z.x=60+i*40;z.y=200+(i%3)*30;z.hp=z.maxHp=hp||1e7;z.evoT=-1e9;}};
