t('kuasa belum dimiliki tak boleh guna',()=>{const s=defaultSave(0);const b=new Battle(s,3,R());A.strictEqual(b.usePower('bom'),false)});
t('meteor jatuh dan cederakan',()=>{const b=mkP();crowd(b,4);b.usePower('meteor');A.ok(b.meteors.length>=5);for(let i=0;i<30*4;i++)b.updatePowers(1/30);A.strictEqual(b.meteors.length,0);A.ok(b.zombies.some(z=>z.hp<z.maxHp))});
