t('ladang duri cederakan zombie dekat pagar',()=>{const b=mkP();crowd(b,1);const z=b.zombies[0];z.y=WALL_Y-60;b.usePower('duri');const h=z.hp;b.updatePowers(1);A.ok(z.hp<h);A.ok(z.slowK>0)});
t('ribut petir menyambar',()=>{const b=mkP();crowd(b,4);b.usePower('petir');for(let i=0;i<30;i++)b.updatePowers(1/30);A.ok(b.fx.some(f=>f.kind==='strike'))});
t('penawar pulihkan & kebal',()=>{const b=mkP();b.wall=10;b.usePower('penawar');A.ok(b.wall>=b.wallMax*0.4);const z=b.spawn('biasa');const w=b.wall;b.hitWall(z);A.strictEqual(b.wall,w)});
