t('integriti statistik asas semua 22 hero',()=>{A.strictEqual(new Set(HERO_ORDER).size,HERO_ORDER.length);HERO_ORDER.forEach(h=>{const meta=HEROES[h];A.ok(meta&&typeof meta.nama==='string'&&meta.nama.length>0,h+' nama');const s=defaultSave(0);s.heroes[h]=1;s.weapons[meta.wpn]=1;s.heroWpn[h]=meta.wpn;const st=heroStats(s,h,0);for(const k of ['dmg','rate','crit','critMul','goldPct'])A.ok(Number.isFinite(st[k]),h+' '+k+' mesti terhingga');A.ok(st.dmg>0&&st.rate>0,h+' statistik positif');});});
